def skill_markdown(item: dict) -> str:
    workflow = "\n".join(f"{index}. {step}" for index, step in enumerate(item["steps"], start=1))
    return f'''---
name: {item["id"]}
description: {item["description"]}
---

# {item["name"]}

## Workflow

{workflow}

## Output contract

{item["output"]}

State evidence, assumptions, uncertainty, and missing capability separately when they affect the result. Stop or defer when a decision-reversing unknown cannot be resolved safely.

## Boundary

{item["boundary"]}

This skill is advisory expertise. MOA owns orchestration, Minister owns strategic judgment, Forge owns engineering implementation, and verification owns completion evidence.

## Evidence basis

Use the relevant parts of the [primary guidance]({item["source"]}) when standards or formal evidence are material. Verify currency before making a time-sensitive claim.
'''


def openai_yaml(item: dict) -> str:
    short = item["description"].split(". Use", 1)[0]
    if len(short) > 64:
        short = short[:61].rstrip() + "..."
    if len(short) < 25:
        short = f"Apply {item['name']} with evidence"
    return f'''interface:
  display_name: "{item["name"]}"
  short_description: "{short.replace('"', '')}"
  default_prompt: "Use ${item["id"]} to complete this task with a traceable, bounded result."
'''


def registry_entry(item: dict) -> dict:
    location = SKILLS_ROOT / item["id"]
    return {
        "id": item["id"],
        "name": item["name"],
        "description": item["description"],
        "category": item["category"],
        "capabilities": item["capabilities"],
        "triggers": item["triggers"],
        "location": str(location),
        "scope": "shared",
        "publisher": {"name": "personal-ai-os", "type": "personal"},
        "source": {"type": "local", "uri": str(location), "repository": None, "commit": None},
        "version": "1.0.0",
        "license": "UNLICENSED",
        "trust_level": "VERIFIED",
        "status": "AVAILABLE",
        "enabled": True,
        "installed": True,
        "dependencies": [],
        "conflicts": [],
        "recommended_agents": item["agents"],
        "activation_cost": item["cost"],
        "compatibility": {"runtime": "codex-agent-skills", "minimum_version": "0.151.0-alpha.7.2", "notes": "User-scoped skill discovered from CODEX_HOME/skills."},
        "quality": {"score": 64, "maximum": 75, "rubric_version": "0.1.0"},
        "notes": f"Canonical AI OS v1.0 skill. Evidence basis: {item['source']}",
        "last_validated": TODAY,
    }


def atomic_write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile("w", encoding="utf-8", dir=path.parent, delete=False) as handle:
        handle.write(text)
        handle.flush()
        os.fsync(handle.fileno())
        temporary = Path(handle.name)
    os.replace(temporary, path)


def main() -> int:
    ids = [item["id"] for item in CATALOG]
    if len(ids) != 29 or len(set(ids)) != 29:
        raise ValueError("v1 catalog must contain 29 unique new skills")
    for item in CATALOG:
        root = SKILLS_ROOT / item["id"]
        atomic_write(root / "SKILL.md", skill_markdown(item))
        atomic_write(root / "agents" / "openai.yaml", openai_yaml(item))

    registry = json.loads(REGISTRY_PATH.read_text(encoding="utf-8"))
    existing = [entry for entry in registry["skills"] if entry["id"] not in set(ids)]
    registry["registry_version"] = "1.0.0"
    registry["skills"] = existing + [registry_entry(item) for item in CATALOG]
    atomic_write(REGISTRY_PATH, json.dumps(registry, indent=2, ensure_ascii=False) + "\n")
    category_names = {
        "research": "Research",
        "product-design": "Product and Design",
        "engineering": "Engineering",
        "ai": "AI",
        "operations-quality": "Operations and Quality",
    }
    lines = ["# AI OS Shared Skill Library v1.0", "", "The 9 reasoning skills remain canonical. The 29 skills below extend the shared library. Skill Broker is infrastructure and is not included in the 38-skill domain total.", ""]
    for category, label in category_names.items():
        lines.extend([f"## {label}", "", "| Skill | Primary capability | Evidence basis |", "| --- | --- | --- |"])
        for item in CATALOG:
            if item["category"] == category:
                lines.append(f"| `{item['id']}` | `{item['capabilities'][0]}` | [Primary guidance]({item['source']}) |")
        lines.append("")
    lines.extend(["## Access contract", "", "`MOA -> capability requirements -> Skill Broker -> Skill Registry -> minimum sufficient shared skills -> selected agent execution -> verification -> Minister final review`", "", "Recommended-agent metadata is advisory. Availability, trust, status, dependencies, and task relevance determine selection. Full skill instructions load only after broker selection.", ""])
    atomic_write(CATALOG_DOC, "\n".join(lines))
    print(f"Materialized {len(CATALOG)} shared skills; registry now has {len(registry['skills'])} entries.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
